import { cacheTag } from 'next/cache'

export type Post = {
  id: string
  title: string
  content: string
  createdAt: string
}

// Simple in-memory store. Replace with your database.
const posts: Post[] = []

export async function getPosts(): Promise<Post[]> {
  'use cache'
  cacheTag('posts')
  return [...posts].reverse()
}

export async function insertPost(data: {
  title: string
  content: string
}): Promise<Post> {
  const post: Post = {
    id: crypto.randomUUID(),
    title: data.title,
    content: data.content,
    createdAt: new Date().toISOString(),
  }
  posts.push(post)
  return post
}

